    '    		 )',
    '    loop',
    '    		',
    '    		rtvalue := vRate.Rate;',
    '    		exit;',
    '    end loop;		  							',
    '    return rtvalue;',
    'end ;')),
  'suppress_change_event', 'N',
  'type', 'FUNCTION_BODY')).to_clob
,p_wait_for_result=>'Y'
);
