  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'begin',
    '',
    'delete from enquiryindentdetail where tno = :P708_TNO;',
    '',
    'insert into enquiryindentdetail',
    '                                (',
    '                                    tno , ',
    '                                    indenttno',
