    '		for vTAC ',
    '				in (',
    '						select',
    '								b.SNo,',
    '								c.TermsAndConditionHeadName,',
    '								c.TermsAndConditionHeadCode,',
    '								b.TermsAndConditionValue',
    '						from ModuleDocTypeWiseTAC a, ModuleDocTypeWiseTACDetail b, TermsAndConditionHead c',
    '						where a.TNo = b.Tno',
