    '		loop',
    '',
    '            insert into ENQUIRYTAC (tno,SNO,',
    '            TermsAndConditionHeadCode ,TermsAndCondition )',
    '            values(:P708_TNO,GLOBALTNO.NEXTVAL,vTAC.TermsAndConditionHeadCode ,',
    '            vTAC.TermsAndConditionValue );',
