wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(41178565993923817)
,p_event_id=>wwv_flow_imp.id(41178031605923816)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-execute-plsql-code'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'items_to_submit', 'P710_TNO,P710_ENQUIRYTNO',
  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'begin',
    '',
    'if :P710_ENQUIRYTNO is not null then',
    '    delete from quotationdetail where tno = :P710_TNO;',
    '',
    'end if;',
    '    for vloop in (select ',
    '                    itemcode , ',
    '                    ITEMSPECIFICATIONCODE , ',
    '                    DESCRIPTION , ',
    '                    QUANTITY1 , ',
    '                    QUANTITY2 ',
    '                from ENQUIRYITEMDETAIL ',
    '                where tno = :P710_ENQUIRYTNO)',
    '    loop',
    '        insert into QUOTATIONDETAIL ',
    '        (tno,',
    '        sno,',
    '        itemcode,',
    '        ITEMSPECIFICATIONCODE,',
    '        DESCRIPTION,',
    '        QUANTITY1,',
    '        QUANTITY2',
    '        )',
    '        values (',
    '            :P710_TNO,',
    '            globaltno.nextval,',
    '            vloop.itemcode,',
    '            vloop.ITEMSPECIFICATIONCODE,',
    '            vloop.DESCRIPTION,',
    '            vloop.QUANTITY1,',
    '            vloop.QUANTITY2',
    '        );',
    '    end loop;',
    'end;')),
  'show_processing', 'N')).to_clob
,p_wait_for_result=>'Y'
);
