wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(41070432871923780)
,p_process_sequence=>50
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_imp.id(364448803368967367)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'QuotationDetail - Save Interactive Grid Data'
,p_static_id=>'quotationdetail-save-interactive-grid-data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Begin',
'    case :APEX$ROW_STATUS',
'        when ''C'' then',
'            Insert Into QUOTATIONDETAIL (                 ',
'                    TNO,',
'					SNO,',
'					SERIALNO,',
'					ITEMCODE,',
'					ITEMSPECIFICATIONCODE,',
'					DESCRIPTION,',
'					QUANTITY1,',
'					QUANTITY2,',
'					RATEMEASURINGUNITCODE,',
'					RATE,',
'					AMOUNT,',
'					FOOTERAMOUNT,',
'					TOTALAMOUNT,',
'					REMARK,',
'					WITHOUTDISCOUNTRATE,',
'					DISCOUNTPERCENTAGE,',
'					DISCOUNTRATE,',
'					HSNCODE,',
'					ISRATEINCLUSIVETAX,',
'					RATEAFTERDISCOUNT',
'',
'            )',
'            Values (',
'                :TNO,',
'				:SNO,',
'				:SERIALNO,',
'				:ITEMCODE,',
'				:ITEMSPECIFICATIONCODE,',
'				:DESCRIPTION,',
'				:QUANTITY1,',
'				:QUANTITY2,',
'				:RATEMEASURINGUNITCODE,',
'				:RATE,',
'				:AMOUNT,',
'				:FOOTERAMOUNT,',
'				:TOTALAMOUNT,',
'				:REMARK,',
'				:WITHOUTDISCOUNTRATE,',
'				:DISCOUNTPERCENTAGE,',
'				:DISCOUNTRATE,',
'				:HSNCODE,',
'				:ISRATEINCLUSIVETAX,',
'				:RATEAFTERDISCOUNT',
'              ',
'',
'            );',
'        ',
'        when ''U'' then',
'            update QUOTATIONDETAIL Set',
'                  TNO = :TNO,',
'				SNO = :SNO,',
'				SERIALNO = :SERIALNO,',
'				ITEMCODE = :ITEMCODE,',
'				ITEMSPECIFICATIONCODE = :ITEMSPECIFICATIONCODE,',
'				DESCRIPTION = :DESCRIPTION,',
'				QUANTITY1 = :QUANTITY1,',
'				QUANTITY2 = :QUANTITY2,',
'				RATEMEASURINGUNITCODE = :RATEMEASURINGUNITCODE,',
'				RATE = :RATE,',
'				AMOUNT = :AMOUNT,',
'				FOOTERAMOUNT = :FOOTERAMOUNT,',
'				TOTALAMOUNT = :TOTALAMOUNT,',
'				REMARK = :REMARK,',
'				WITHOUTDISCOUNTRATE = :WITHOUTDISCOUNTRATE,',
'				DISCOUNTPERCENTAGE = :DISCOUNTPERCENTAGE,',
'				DISCOUNTRATE = :DISCOUNTRATE,',
'				HSNCODE = :HSNCODE,',
'				ISRATEINCLUSIVETAX = :ISRATEINCLUSIVETAX,',
'				RATEAFTERDISCOUNT = :RATEAFTERDISCOUNT           ',
'            WHERE TNO = :P710_TNO',
'              and rowid = :ROWID;',
'',
'        when ''D'' then',
'            Delete From QUOTATIONDETAIL',
'            Where TNo = :P710_TNO',
'              and SNO = :SNO',
'              ;',
'    end case;',
'exception when others then',
'    raise_application_error(-20010, sqlerrm);',
'End;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>9027916337514032
);
